import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as s}from"./chunks/EN.P9aPnFBv.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as n,o as p,c as r,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"Inter-app","description":"","frontmatter":{"source_hash":"4a69400131","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/interapp.md","filePath":"it/use/interapp.md"}'),d={name:"it/use/interapp.md"};function c(u,t,m,h,v,g){return p(),r("div",null,[...t[0]||(t[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> Impostazioni Inter-app</p></div><br><p>Impostazioni Inter-app offre due modi per far comunicare xDrip con altre app: la trasmissione locale (interna a questo telefono) e il web service (interno ed esterno).</p><h3 id="local-broadcast" tabindex="-1">Trasmissione locale <a class="header-anchor" href="#local-broadcast" aria-label="Permalink to &quot;Trasmissione locale {#local-broadcast}&quot;">​</a></h3><p>Trasmetti localmente fa inviare a xDrip messaggi interni che possono essere usati da altre app come Nightwatch o AAPS.</p><div class="admonition xdripitem"><p class="admonition-title">Trasmetti localmente <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Abilita trasmissione locale di dati in modo da altre applicazioni (ad es. NightWatch) possano importare nuovi valori</p></div><p>Se usi plugin di calibrazione o il filtraggio, puoi scegliere di trasmettere i dati grezzi o quelli filtrati/calibrati.</p><div class="admonition xdripitem"><p class="admonition-title">Invia Glicemia Visualizzata <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Usa filtraggio del rumore e plugins (se abilitati) per il valore trasmesso</p></div><p>Per sicurezza puoi anche bloccare la trasmissione dei dati rumorosi. Per impostazione predefinita, solo i dati con rumore estremo non vengono trasmessi.</p><div class="admonition xdripitem"><p class="admonition-title">Blocco rumore</p><p> Livello a quale i dati rumorosi non dovrebbero essere trasmessi perché potrebbe confondere le app riceventi</p></div><p>Le app e i telefoni recenti dovrebbero accettare il broadcast compatibile. Non togliere la spunta.</p><div class="admonition xdripitem"><p class="admonition-title">Broadcast compatibile <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Invia trasmissioni senza usare il vecchio modello di permesso</p></div><p>Puoi indicare un ricevitore identificato se vuoi che xDrip invii i messaggi solo a un&#39;app specifica. Uno degli usi più comuni è quando xDrip è la sorgente dati di <a href="https://androidaps.readthedocs.io/en/latest/Configuration/xdrip.html#identify-receiver" target="_blank" rel="noreferrer">AAPS</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Identifica ricevitore</p><p> Invia dati solo al package nominato</p></div><h5 id="receiving-from-nsclient" tabindex="-1">Ricezione da NSClient. <a class="header-anchor" href="#receiving-from-nsclient" aria-label="Permalink to &quot;Ricezione da NSClient. {#receiving-from-nsclient}&quot;">​</a></h5><p>Con questa funzione xDrip può anche ricevere messaggi: puoi attivare o disattivare la ricezione di dati e trattamenti da altre app che li trasmettono.</p><div class="admonition xdripitem"><p class="admonition-title">Accetta Glucosio <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Usa i dati di glicemia ricevuti dall&#39;app NSClient</p></div><div class="admonition xdripitem"><p class="admonition-title">Accetta trattamenti <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Processa i trattamenti ricevuti dall&#39;app NSClient</p></div><p>Puoi attivare o disattivare (<strong>disattivalo con AAPS!!!</strong>) il suono riprodotto dopo l&#39;aggiornamento del profilo di xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Importa Suoni <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Suona durante l&#39;importazione di dati significativi come i profili</p></div><p>Fai attenzione quando accetti calibrazioni da altre app.</p><div class="admonition xdripitem"><p class="admonition-title">Accetta calibrazione <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utilizza le calibrazioni ricevute da altre applicazioni</p></div><h3 id="web-service" tabindex="-1">Web Service <a class="header-anchor" href="#web-service" aria-label="Permalink to &quot;Web Service {#web-service}&quot;">​</a></h3><p>Documentazione originale <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/technical/Local_Web_Services.md" target="_blank" rel="noreferrer">qui</a>.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Se hai un&#39;altra app che usa la porta 17580 (come Diabox), devi disattivare questa funzione.<br> Nota che il servizio non è disponibile in http sicuro e le app <a href="./../smartwatch/smartwatch.html#fitbit">Fitbit</a> recenti potrebbero non accettarne i dati.</p></div><p>Il web service apre un servizio web locale sul dispositivo per permettere ad altri dispositivi (smartwatch) e app di riceverne i dati.<br> Il server web risponde alle richieste all&#39;indirizzo <code>127.0.0.1</code> porta <code>17580</code></p><div class="admonition xdripitem"><p class="admonition-title">xDrip Web Service <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Opera un server web locale per interagire con smartwatch Fitbit ed altri</p></div><p>Per impostazione predefinita il web service è disponibile solo sul tuo dispositivo; puoi aprirlo perché altri dispositivi della rete possano accedervi. Assicurati di avere davvero bisogno di questa funzione e di comprenderne le implicazioni per la sicurezza. Assicurati di aver impostato uno Shared Secret.</p><div class="admonition xdripitem"><p class="admonition-title">Apri Web Service <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Accetta connessioni da qualsiasi rete invece che solo all&#39;interno di questo dispositivo. Ci sono implicazioni di sicurezza per abilitarlo! La password Shared Secret sarà richiesta se impostata.</p></div><div class="admonition xdripitem"><p class="admonition-title">xDrip Web Service Segret</p><p> Shared Secret per il servizio web aperto (dovrebbe corrispondere all&#39;API segret di Nightscout)</p></div><h4 id="open-option" tabindex="-1">Opzione Apri Web Service <a class="header-anchor" href="#open-option" aria-label="Permalink to &quot;Opzione Apri Web Service {#open-option}&quot;">​</a></h4><p>Il servizio ha un&#39;opzione <code>Apri Web Service</code>. Se è attiva, le connessioni possono arrivare da qualsiasi interfaccia di rete invece di essere limitate alla sola rete di loopback interna al dispositivo. Di solito attivare questa opzione espone la connessione wifi / lan / bluetooth pan del dispositivo, ma è possibile che venga esposta anche tramite la rete cellulare, se l&#39;operatore supporta gli indirizzi IP pubblici.</p><p>Fai molta attenzione ad attivare questa opzione, perché rende accessibili funzioni potenti, ad esempio l&#39;interfaccia tasker. È meglio usarla insieme all&#39;opzione di autenticazione descritta qui sotto.</p><h4 id="authentication" tabindex="-1">Autenticazione <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Autenticazione {#authentication}&quot;">​</a></h4><p>Per motivi di sicurezza (chiunque sulla rete può accedere a questo servizio) dovresti proteggerlo con una password; se hai un sito Nightscout, usa il tuo API_SECRET.</p><p>Se <code>xDrip Web Service Segret</code> è impostato su qualcosa di diverso da una stringa vuota (il valore predefinito), le richieste che arrivano dalle reti aperte non di loopback devono fornire un header http <code>api-secret</code> contenente l&#39;hash SHA1 della stessa password segreta, altrimenti la connessione viene rifiutata. Le informazioni sul rifiuto vengono salvate nel Registro eventi e restituite nella risposta http. Quando una connessione viene rifiutata, viene impostato il codice di risultato 403 (forbidden).</p><p>Inoltre, se un client fornisce l&#39;header <code>api-secret</code>, la richiesta viene rifiutata anche se il secret di xDrip non è impostato. Questa funzione serve a garantire ai dispositivi client che si stanno collegando all&#39;istanza di xDrip giusta (usando secret diversi). Può essere importante, ad esempio, quando si usa un loop.</p><p>L&#39;autenticazione non è richiesta sull&#39;interfaccia di rete locale di loopback (127.0.0.1)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api-secret: 915858afa2278f25527f192038108346164b47f2</span></span></code></pre></div><p>Qui sopra è mostrato l&#39;header http per la password <code>Abc</code></p><h4 id="nightscout-pebble-endpoint" tabindex="-1">Endpoint Pebble di Nightscout <a class="header-anchor" href="#nightscout-pebble-endpoint" aria-label="Permalink to &quot;Endpoint Pebble di Nightscout {#nightscout-pebble-endpoint}&quot;">​</a></h4><p><code>/pebble</code> emula lo stesso URL di Nightscout: con un quadrante che lo supporta, puoi inserire l&#39;indirizzo nel quadrante, ad esempio impostando l&#39;endpoint dei dati del quadrante Pebble Nightscout su:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/pebble</span></span></code></pre></div><h4 id="sgvjson-endpoint" tabindex="-1">Endpoint sgv.json <a class="header-anchor" href="#sgvjson-endpoint" aria-label="Permalink to &quot;Endpoint sgv.json {#sgvjson-endpoint}&quot;">​</a></h4><p><code>/sgv.json</code> emula <code>/api/v1/entries/sgv.json?count=24</code> di Nightscout</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json</span></span></code></pre></div><p>Il primo record contiene un&#39;indicazione sulle unità usate: <code>units_hint</code> sarà <code>mgdl</code> o <code>mmol</code> per indicare la preferenza dell&#39;utente, ma i valori vengono sempre inviati in mgdl</p><p>Puoi accedere anche all&#39;endpoint dei passi aggiungendo un parametro alla query</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?steps=1234</span></span></code></pre></div><p>In questo caso cerca il numero <code>steps_result</code> nel primo record della risposta json: 200 indica successo, qualsiasi altro valore indica che l&#39;impostazione dei passi non è riuscita. Il valore dei passi deve essere il contapassi cumulativo attuale del dispositivo.</p><p>Puoi accedere anche all&#39;endpoint della frequenza cardiaca aggiungendo un parametro alla query</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?heart=123</span></span></code></pre></div><p>In questo caso cerca il numero <code>heart_result</code> nel primo record della risposta json: 200 indica successo, qualsiasi altro valore indica che l&#39;impostazione dei bpm non è riuscita. Il valore deve essere la frequenza cardiaca attuale in bpm del dispositivo.</p><p>Puoi combinare i due come in una normale query string:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?steps=1234&amp;heart=123</span></span></code></pre></div><p>C&#39;è anche l&#39;opzione <code>brief_mode=Y</code>, che puoi usare per escludere alcuni campi dai risultati e ridurre la dimensione della risposta.</p><p>C&#39;è anche l&#39;opzione <code>no_empty=Y</code>, che puoi usare perché un insieme di dati vuoto restituisca <code>&quot;&quot;</code> invece di <code>&quot;[]&quot;</code></p><p>C&#39;è anche l&#39;opzione <code>all_data=Y</code>, che puoi usare per ottenere in più i dati della sessione del sensore precedente.</p><p>C&#39;è anche l&#39;opzione <code>sensor=Y</code>, che puoi usare per ottenere i dati sull&#39;età del sensore</p><p>C&#39;è anche l&#39;opzione <code>collector=Y</code>, che puoi usare per ottenere i messaggi di avviso del collector. Se il messaggio è vuoto non viene restituito nulla.</p><p>Puoi accedere anche all&#39;endpoint tasker aggiungendo un parametro alla query</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?tasker=osnooze</span></span></code></pre></div><p>cerca <code>tasker_result</code> nella prima riga della risposta json per sapere se l&#39;operazione è riuscita o no.</p><p><code>OSNOOZE</code> è la sospensione opportunistica, che puoi richiamare anche quando nessun avviso sta suonando</p><p><code>SNOOZE</code> è la sospensione tasker tradizionale, che invia la sospensione ai follower e usa più cpu</p><h4 id="treatmentsjson-endpoint" tabindex="-1">Endpoint treatments.json <a class="header-anchor" href="#treatmentsjson-endpoint" aria-label="Permalink to &quot;Endpoint treatments.json {#treatmentsjson-endpoint}&quot;">​</a></h4><p><code>/treatments.json</code> emula <code>/api/v1/treatments.json?count=24</code> di Nightscout</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/treatments.json</span></span></code></pre></div><h4 id="statusjson-endpoint" tabindex="-1">Endpoint status.json <a class="header-anchor" href="#statusjson-endpoint" aria-label="Permalink to &quot;Endpoint status.json {#statusjson-endpoint}&quot;">​</a></h4><p>Implementa un piccolo sottoinsieme dei dati che potresti ricevere dallo status.json di Nightscout</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/status.json</span></span></code></pre></div><p>I risultati hanno questo aspetto:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;thresholds&quot;:{&quot;bgHigh&quot;:9.4,&quot;bgLow&quot;:3.9}}</span></span></code></pre></div><p>Le soglie alta e bassa impostate nell&#39;app, espresse nelle unità locali.</p><h4 id="libre-2-endpoint" tabindex="-1">Endpoint Libre 2 <a class="header-anchor" href="#libre-2-endpoint" aria-label="Permalink to &quot;Endpoint Libre 2 {#libre-2-endpoint}&quot;">​</a></h4><p><code>/Libre2ConnectCode.json</code> restituisce il buffer di sblocco Bluetooth e l&#39;indirizzo MAC del dispositivo.</p><p>È usato da <a href="./sync.html#whole-house">whole house</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/Libre2ConnectCode.json</span></span></code></pre></div><h4 id="tasker-endpoint" tabindex="-1">Endpoint Tasker <a class="header-anchor" href="#tasker-endpoint" aria-label="Permalink to &quot;Endpoint Tasker {#tasker-endpoint}&quot;">​</a></h4><p>L&#39;endpoint <code>/tasker</code> ti permette di inviare richieste all&#39;interfaccia tasker via http. Così un quadrante che supporta solo endpoint web (ad es. FitBit) può inviare una richiesta di sospensione come questa:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/tasker/SNOOZE</span></span></code></pre></div><h4 id="steps-endpoint" tabindex="-1">Endpoint dei passi <a class="header-anchor" href="#steps-endpoint" aria-label="Permalink to &quot;Endpoint dei passi {#steps-endpoint}&quot;">​</a></h4><p><code>/steps</code> permette di impostare i dati attuali del contapassi</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/steps/set/1234</span></span></code></pre></div><p>Deve essere il contapassi cumulativo attuale del dispositivo che misura i passi, non un dato storico.</p><h4 id="heart-endpoint" tabindex="-1">Endpoint della frequenza cardiaca <a class="header-anchor" href="#heart-endpoint" aria-label="Permalink to &quot;Endpoint della frequenza cardiaca {#heart-endpoint}&quot;">​</a></h4><p><code>/heart</code> permette di impostare la frequenza cardiaca attuale in bpm</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/heart/set/123/1</span></span></code></pre></div><p>Deve essere la frequenza cardiaca attuale in BPM del dispositivo di misura, non un dato storico. Il primo parametro sono i BPM e il secondo la precisione. Se non sei sicuro del parametro di precisione, impostalo semplicemente a 1.</p><br><h3 id="broadcast-service-api" tabindex="-1">Servizio di Trasmissione API <a class="header-anchor" href="#broadcast-service-api" aria-label="Permalink to &quot;Servizio di Trasmissione API {#broadcast-service-api}&quot;">​</a></h3><p>Questo servizio permette di trasmettere i valori di xDrip tramite un&#39;API e può essere usato da app esterne come <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration" target="_blank" rel="noreferrer">WatchDrip+</a> (attiva la funzione per WatchDrip+).</p><div class="admonition xdripitem"><p class="admonition-title">Servizio di Trasmissione API <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Abilita la comunicazione tra xDrip e applicazioni terze parti utilizzando la nuova API</p></div><div class="admonition xdripitem"><p class="admonition-title">Abilita il trasferimento dell&#39;IoB nelle API <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Abilita la segnalazione dei valori IoB nell&#39;endpoint Web Service API utilizzato da alcuni smartwatch</p></div><div class="admonition xdripitem"><p class="admonition-title">Recupera IoB dall&#39;app compagno <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Recupera il valore IoB dall&#39;app compagno in esecuzione sullo stesso dispositivo, come l&#39;app Omnipod 5</p></div><br><h3 id="google-health-connect" tabindex="-1">Google Health Connect <a class="header-anchor" href="#google-health-connect" aria-label="Permalink to &quot;Google Health Connect {#google-health-connect}&quot;">​</a></h3><p>Puoi condividere informazioni con Google Health.</p><div class="admonition xdripitem"><p class="admonition-title">Google Health Connect</p><p> Invia e ricevi dati da Google Health Connect e Google Fit</p></div><p>Devi avere installato sul dispositivo <a href="https://play.google.com/store/apps/details?id=com.google.android.apps.healthdata&amp;hl=en&amp;gl=US" target="_blank" rel="noreferrer">Health Connect</a>, disponibile per Android 8 e successivi.</p><div class="admonition xdripitem"><p class="admonition-title">Usa Health Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Richiede Android 8+ e Google app compagno oppure Android 14+</p></div><p>Puoi poi decidere di usare i dati in entrata e di consentire quelli in uscita.</p><p>xDrip può condividere passi, frequenza cardiaca e glicemia con Google Health.</p><div class="admonition xdripitem"><p class="admonition-title">Ottieni dati da Health Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Invia dati a Health Connect <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Gestione permessi</p><p> Apri le impostazioni di Health Connect per gestire manualmente i permessi</p></div><p>Su alcune versioni di Android (in particolare 15 e 16) xDrip non può aprire direttamente la propria schermata dei permessi di Health Connect. Apre allora l&#39;app Health Connect: vai in <em>Autorizzazioni app</em> e seleziona xDrip per gestirli. Se Health Connect non si può aprire affatto, un messaggio ti chiede di aprire tu stesso l&#39;app Health Connect e di gestire lì i permessi di xDrip.</p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',108)])])}const C=n(d,[["render",c]]);export{y as __pageData,C as default};
